#!/usr/bin/env node
/**
 * Automatic Correction with Iterative Validation
 * 
 * Implements iterative feedback cycle:
 * 1. Validate content semantically
 * 2. Detect template/content mismatches
 * 3. Generate corrected versions with suggested templates
 * 4. Re-validate corrections
 * 5. Repeat until all diagrams pass or max iterations reached
 * 
 * This is the "right and hard things" implementation - proper engineering feedback loop.
 */

import fs from "fs";
import path from "path";
import { parseArgs } from "util";
import { validateSemantics, generateCorrections } from "./semantic-validate.mjs";

/**
 * Template placeholder mappings for auto-conversion
 */
const TEMPLATE_CONVERSIONS = {
  // Flowchart (sequential) → State-diagram
  'flowchart->state-diagram': (placeholders) => {
    const converted = {};
    let stateIndex = 1;
    let transitionIndex = 1;

    // Extract sequential actions
    const actions = Object.entries(placeholders)
      .filter(([k, v]) => k.includes('ACTION') || k.includes('LABEL'))
      .sort((a, b) => a[0].localeCompare(b[0]));

    for (const [key, value] of actions) {
      converted[`STATE_${stateIndex}`] = value;
      if (stateIndex > 1) {
        converted[`TRANSITION_${transitionIndex}_LABEL`] = 'Next';
        transitionIndex++;
      }
      stateIndex++;
    }

    return converted;
  },

  // Flowchart (sequential) → Timeline
  'flowchart->timeline': (placeholders) => {
    const converted = {};
    let eventIndex = 1;

    const actions = Object.entries(placeholders)
      .filter(([k, v]) => k.includes('ACTION') || k.includes('LABEL'))
      .sort((a, b) => a[0].localeCompare(b[0]));

    for (const [key, value] of actions) {
      converted[`EVENT_${eventIndex}`] = value;
      converted[`DATE_${eventIndex}`] = `Phase ${eventIndex}`;
      eventIndex++;
    }

    return converted;
  },

  // Architecture → Flowchart
  'architecture->flowchart': (placeholders) => {
    const converted = {};
    let actionIndex = 1;

    const components = Object.entries(placeholders)
      .filter(([k, v]) => k.includes('COMPONENT') && k.includes('LABEL'))
      .sort((a, b) => a[0].localeCompare(b[0]));

    if (components.length > 0) {
      converted.START_LABEL = components[0][1];
    }

    for (let i = 1; i < components.length; i++) {
      converted[`ACTION_${actionIndex}`] = components[i][1];
      actionIndex++;
    }

    if (components.length > 0) {
      converted.END_LABEL = 'Complete';
    }

    return converted;
  },

  // Sequence (single-actor) → Flowchart
  'sequence->flowchart': (placeholders) => {
    const converted = {};
    let actionIndex = 1;

    const messages = Object.entries(placeholders)
      .filter(([k, v]) => k.includes('MESSAGE'))
      .sort((a, b) => a[0].localeCompare(b[0]));

    if (messages.length > 0) {
      converted.START_LABEL = messages[0][1];
    }

    for (let i = 1; i < messages.length - 1; i++) {
      converted[`ACTION_${actionIndex}`] = messages[i][1];
      actionIndex++;
    }

    if (messages.length > 1) {
      converted.END_LABEL = messages[messages.length - 1][1];
    }

    return converted;
  },

  // Comparison (no coords) → Comparison-table
  'comparison->comparison-table': (placeholders) => {
    const converted = {};

    // Extract options
    const options = Object.entries(placeholders)
      .filter(([k, v]) => k.includes('OPTION') && !k.includes('_'));

    if (options.length >= 2) {
      converted.OPTION_1_TITLE = options[0][1];
      converted.OPTION_2_TITLE = options[1][1];
    }

    // Extract criteria
    const criteria = Object.entries(placeholders)
      .filter(([k, v]) => k.includes('CRITERION') || k.includes('LABEL'))
      .sort((a, b) => a[0].localeCompare(b[0]));

    for (let i = 0; i < Math.min(criteria.length, 4); i++) {
      const criterionIndex = i + 1;
      converted[`OPTION_1_CRITERION_${criterionIndex}`] = criteria[i][1];
      converted[`OPTION_2_CRITERION_${criterionIndex}`] = criteria[i][1];
    }

    return converted;
  },

  // Gantt (no temporal) → Timeline
  'gantt->timeline': (placeholders) => {
    const converted = {};
    let eventIndex = 1;

    const tasks = Object.entries(placeholders)
      .filter(([k, v]) => k.includes('TASK') && !k.includes('_'))
      .sort((a, b) => a[0].localeCompare(b[0]));

    for (const [key, value] of tasks) {
      converted[`EVENT_${eventIndex}`] = value;
      converted[`DATE_${eventIndex}`] = `Phase ${eventIndex}`;
      eventIndex++;
    }

    return converted;
  }
};

/**
 * Attempt to auto-convert placeholders to suggested template
 */
function convertPlaceholders(fromTemplate, toTemplate, originalPlaceholders) {
  const conversionKey = `${fromTemplate}->${toTemplate}`;

  if (TEMPLATE_CONVERSIONS[conversionKey]) {
    return TEMPLATE_CONVERSIONS[conversionKey](originalPlaceholders);
  }

  // No conversion available - return original
  return null;
}

/**
 * Iterative validation and correction cycle
 */
async function iterativeCorrection(content, maxIterations = 3) {
  const history = [];
  let iteration = 0;
  let currentContent = JSON.parse(JSON.stringify(content)); // Deep copy

  console.log(`\n🔄 Starting iterative correction cycle (max ${maxIterations} iterations)\n`);

  while (iteration < maxIterations) {
    iteration++;
    console.log(`\n${'─'.repeat(80)}`);
    console.log(`Iteration ${iteration}/${maxIterations}`);
    console.log(`${'─'.repeat(80)}\n`);

    let allPassed = true;
    const corrections = [];

    // Validate all diagrams
    for (const [index, diagram] of currentContent.diagrams.entries()) {
      const validation = validateSemantics(diagram.template, diagram.placeholders);

      console.log(`📊 Diagram ${index + 1}: ${diagram.template}`);

      if (validation.passed && validation.warnings.length === 0) {
        console.log(`   ✅ PASS\n`);
        continue;
      }

      allPassed = false;

      // Print issues
      if (validation.errors.length > 0) {
        console.log(`   ❌ Errors: ${validation.errors.length}`);
        for (const error of validation.errors) {
          console.log(`      - ${error.message}`);
        }
      }

      if (validation.warnings.length > 0) {
        console.log(`   ⚠️  Warnings: ${validation.warnings.length}`);
        for (const warning of validation.warnings) {
          console.log(`      - ${warning.message}`);
        }
      }

      // Generate corrections
      const suggestedCorrections = generateCorrections(validation, diagram);

      if (suggestedCorrections.length > 0) {
        const best = suggestedCorrections[0];
        console.log(`\n   💡 Auto-correction available:`);
        console.log(`      ${diagram.template} → ${best.suggestedTemplate} (${(best.confidence * 100).toFixed(0)}% confidence)`);
        console.log(`      Reason: ${best.reason}`);

        // Attempt conversion
        const convertedPlaceholders = convertPlaceholders(
          diagram.template,
          best.suggestedTemplate,
          diagram.placeholders
        );

        if (convertedPlaceholders) {
          console.log(`      ✅ Placeholder conversion available\n`);
          corrections.push({
            index,
            from: diagram.template,
            to: best.suggestedTemplate,
            placeholders: convertedPlaceholders,
            confidence: best.confidence,
            reason: best.reason
          });
        } else {
          console.log(`      ⚠️  Manual placeholder mapping required\n`);
        }
      } else {
        console.log(`\n   ℹ️  No auto-corrections available\n`);
      }
    }

    // Apply corrections
    if (corrections.length > 0) {
      console.log(`\n🔧 Applying ${corrections.length} corrections...\n`);

      for (const correction of corrections) {
        console.log(`   ${correction.index + 1}. ${correction.from} → ${correction.to}`);
        currentContent.diagrams[correction.index].template = correction.to;
        currentContent.diagrams[correction.index].placeholders = correction.placeholders;
        currentContent.diagrams[correction.index]._correctionHistory = currentContent.diagrams[correction.index]._correctionHistory || [];
        currentContent.diagrams[correction.index]._correctionHistory.push({
          iteration,
          from: correction.from,
          to: correction.to,
          reason: correction.reason,
          confidence: correction.confidence
        });
      }

      history.push({
        iteration,
        corrections: corrections.length,
        details: corrections
      });
    } else if (!allPassed) {
      console.log(`\n⚠️  Issues detected but no auto-corrections available. Stopping.\n`);
      break;
    }

    // Check if all passed
    if (allPassed) {
      console.log(`\n✅ All diagrams passed validation!\n`);
      break;
    }
  }

  // Final summary
  console.log(`\n${'═'.repeat(80)}`);
  console.log(`Final Results`);
  console.log(`${'═'.repeat(80)}\n`);

  console.log(`Iterations: ${iteration}/${maxIterations}`);
  console.log(`Total corrections applied: ${history.reduce((sum, h) => sum + h.corrections, 0)}\n`);

  if (history.length > 0) {
    console.log(`Correction history:`);
    for (const record of history) {
      console.log(`  Iteration ${record.iteration}: ${record.corrections} corrections`);
      for (const detail of record.details) {
        console.log(`    - Diagram ${detail.index + 1}: ${detail.from} → ${detail.to} (${detail.reason})`);
      }
    }
    console.log();
  }

  return {
    iterations: iteration,
    originalContent: content,
    correctedContent: currentContent,
    history
  };
}

/**
 * CLI entry point
 */
if (import.meta.url === `file://${process.argv[1]}`) {
  const { values: args } = parseArgs({
    options: {
      content: { type: "string", short: "c" },
      out: { type: "string", short: "o" },
      maxIterations: { type: "string", default: "3" }
    },
    strict: true
  });

  if (!args.content) {
    console.error('Usage: node auto-correct.mjs --content content.json [--out corrected.json] [--maxIterations 3]');
    process.exit(1);
  }

  const content = JSON.parse(fs.readFileSync(args.content, 'utf-8'));
  const maxIterations = parseInt(args.maxIterations);

  const result = await iterativeCorrection(content, maxIterations);

  if (args.out) {
    fs.writeFileSync(args.out, JSON.stringify(result.correctedContent, null, 2));
    console.log(`\n💾 Corrected content saved to: ${args.out}\n`);

    // Also save correction report
    const reportPath = args.out.replace('.json', '-report.json');
    fs.writeFileSync(reportPath, JSON.stringify({
      iterations: result.iterations,
      history: result.history,
      summary: {
        totalCorrections: result.history.reduce((sum, h) => sum + h.corrections, 0),
        converged: result.iterations < maxIterations
      }
    }, null, 2));
    console.log(`📊 Correction report saved to: ${reportPath}\n`);
  }
}

export { iterativeCorrection, convertPlaceholders };

#!/usr/bin/env node
/**
 * Mermaid Diagrams Generator
 * 
 * Renders Mermaid diagrams from pre-generated content JSON files.
 * Designed to work with AI subagent patterns.
 * 
 * Usage:
 *   node generate.mjs --content diagrams/chapter-01/content.json --out diagrams/chapter-01
 */

import fs from "fs";
import path from "path";
import { parseArgs } from "util";
import { fileURLToPath } from "url";
import { execSync } from "child_process";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const TEMPLATES_DIR = path.join(__dirname, "../assets");

// Parse arguments
const { values: args } = parseArgs({
  options: {
    content: { type: "string", short: "c" },
    out: { type: "string", short: "o", default: "./diagrams" },
  },
  strict: true,
});

if (!args.content) {
  console.error("Error: --content required.");
  console.error("Usage: node generate.mjs --content content.json --out output-dir");
  process.exit(1);
}

const outDir = args.out;

// Ensure output directory exists
fs.mkdirSync(outDir, { recursive: true });

// Load content JSON
let content;
try {
  content = JSON.parse(fs.readFileSync(args.content, "utf-8"));
} catch (error) {
  console.error(`❌ Failed to load content file: ${error.message}`);
  process.exit(1);
}

console.log(`\n📖 Rendering diagrams from: ${args.content}`);
console.log(`📊 Found ${content.diagrams.length} diagrams to render\n`);

/**
 * Validate content before rendering
 */
function validateContent(templateContent, template, placeholders) {
  const warnings = [];

  // Check 1: Unresolved placeholders
  const unresolvedMatches = templateContent.match(/\{\{[A-Z_0-9]+\}\}/g);
  if (unresolvedMatches) {
    warnings.push(`⚠️  Unresolved placeholders: ${unresolvedMatches.join(", ")}`);
  }

  // Check 2: Text length (readability)
  const maxLengths = {
    'architecture': 50,
    'flowchart': 40,
    'sequence': 30,
    'concept-map': 35,
    'radial-concept': 40,
    'timeline': 25,
    'comparison': 35,
    'comparison-table': 40,
    'gantt': 40,
    'mindmap': 30,
    'class-diagram': 35,
    'state-diagram': 30
  };

  const maxLength = maxLengths[template] || 50;
  for (const [key, value] of Object.entries(placeholders)) {
    if (typeof value === 'string' && value.length > maxLength) {
      warnings.push(`⚠️  ${key}: "${value}" (${value.length} chars, recommend <${maxLength})`);
    }
  }

  // Check 3: Special characters that might break Mermaid
  const problematicChars = /[<>{}[\]]/;
  for (const [key, value] of Object.entries(placeholders)) {
    if (typeof value === 'string' && problematicChars.test(value)) {
      warnings.push(`⚠️  ${key}: contains special characters (<>{}[]) that may break rendering`);
    }
  }

  return warnings;
}

/**
 * Render a single diagram from content
 */
async function renderDiagramFromContent(diagramData, index) {
  const { template, placeholders } = diagramData;
  const templatePath = path.join(TEMPLATES_DIR, `${template}.mmd`);

  if (!fs.existsSync(templatePath)) {
    console.error(`   ❌ Template not found: ${template}`);
    return null;
  }

  let templateContent = fs.readFileSync(templatePath, "utf-8");

  // Fill template with placeholders
  for (const [key, value] of Object.entries(placeholders)) {
    templateContent = templateContent.replaceAll(`{{${key}}}`, value);
  }

  // Validate before saving
  const warnings = validateContent(templateContent, template, placeholders);
  if (warnings.length > 0) {
    console.log(`\n⚠️  Validation warnings for ${template}:`);
    warnings.forEach(w => console.log(`   ${w}`));
    console.log();
  }

  // Save .mmd file
  const mmdPath = path.join(outDir, `diagram-${String(index + 1).padStart(2, "0")}-${template}.mmd`);
  fs.writeFileSync(mmdPath, templateContent);
  console.log(`   💾 Saved: ${path.basename(mmdPath)}`);

  return { template, mmdPath, index };
}

/**
 * Step 3: Validate and render diagrams
 */
async function renderDiagram({ mmdPath, templateName, index }) {
  const svgPath = mmdPath.replace(".mmd", ".svg");
  const pngPath = mmdPath.replace(".mmd", ".png");

  try {
    // Validate syntax by attempting to render
    execSync(`mmdc -i ${mmdPath} -o ${svgPath} -t default -b transparent`, {
      stdio: "ignore",
    });

    // Also render PNG for compatibility
    execSync(`mmdc -i ${mmdPath} -o ${pngPath} -t default -b transparent -w 1200`, {
      stdio: "ignore",
    });

    console.log(`   ✅ Rendered: ${svgPath} + ${pngPath}`);
    return true;
  } catch (error) {
    console.error(`   ❌ Rendering failed for ${templateName}:`, error.message);
    return false;
  }
}

/**
 * Main execution
 */
async function main() {
  try {
    // Check if mmdc is installed
    try {
      execSync("which mmdc", { stdio: "ignore" });
    } catch {
      console.error("❌ Error: mermaid-cli (mmdc) not found.");
      console.error("   Install with: npm install -g @mermaid-js/mermaid-cli");
      process.exit(1);
    }

    // Render all diagrams from content
    const results = [];
    for (let i = 0; i < content.diagrams.length; i++) {
      const result = await renderDiagramFromContent(content.diagrams[i], i);
      if (result) results.push(result);
    }

    if (results.length === 0) {
      console.error("\n❌ No diagrams rendered successfully.");
      process.exit(1);
    }

    console.log(`\n🎨 Rendering to SVG/PNG...\n`);

    // Render to SVG/PNG
    let successCount = 0;
    for (const result of results) {
      const success = await renderDiagram(result);
      if (success) successCount++;
    }

    console.log(`\n✅ Successfully rendered ${successCount}/${results.length} diagrams in ${outDir}\n`);

    // Save summary
    const summary = {
      source: args.content,
      generated: new Date().toISOString(),
      diagrams: results.map((r, i) => ({
        index: i + 1,
        template: r.template,
        files: {
          source: path.basename(r.mmdPath),
          svg: path.basename(r.mmdPath).replace(".mmd", ".svg"),
          png: path.basename(r.mmdPath).replace(".mmd", ".png"),
        },
      })),
    };

    fs.writeFileSync(
      path.join(outDir, "summary.json"),
      JSON.stringify(summary, null, 2)
    );

  } catch (error) {
    console.error("\n❌ Fatal error:", error.message);
    process.exit(1);
  }
}

main();

#!/usr/bin/env node
/**
 * Semantic Validation Test Runner
 * 
 * Runs comprehensive test suite for semantic validation rules.
 * Tests both positive cases (should pass) and negative cases (should fail with specific suggestions).
 */

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { validateSemantics, generateCorrections } from "./semantic-validate.mjs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const TESTS_FILE = path.join(__dirname, "../tests/semantic-validation-tests.json");

/**
 * Run all tests
 */
function runTests() {
  const testData = JSON.parse(fs.readFileSync(TESTS_FILE, 'utf-8'));

  console.log(`\n🧪 Running ${testData.testSuite} Test Suite\n`);
  console.log(`   Version: ${testData.version}`);
  console.log(`   Tests: ${testData.tests.length}\n`);
  console.log(`${'='.repeat(80)}\n`);

  let passed = 0;
  let failed = 0;
  const failures = [];

  for (const [index, test] of testData.tests.entries()) {
    const testNum = index + 1;
    const result = runTest(test, testNum);

    if (result.passed) {
      passed++;
      console.log(`✅ Test ${testNum}: ${test.name}`);
    } else {
      failed++;
      console.log(`❌ Test ${testNum}: ${test.name}`);
      failures.push({ testNum, test, result });
    }
  }

  console.log(`\n${'='.repeat(80)}\n`);
  console.log(`📊 Results: ${passed}/${testData.tests.length} passed\n`);

  if (failures.length > 0) {
    console.log(`❌ Failed Tests:\n`);
    for (const failure of failures) {
      console.log(`   Test ${failure.testNum}: ${failure.test.name}`);
      console.log(`   Expected: ${JSON.stringify(failure.test.expected)}`);
      console.log(`   Got: ${JSON.stringify(failure.result.actual)}`);
      console.log();
    }
  }

  return failed === 0;
}

/**
 * Run single test
 */
function runTest(test, testNum) {
  const validation = validateSemantics(test.template, test.placeholders);

  const actual = {
    pass: validation.passed && validation.warnings.length === 0,
    errors: validation.errors.length,
    warnings: validation.warnings.length
  };

  if (test.expected.suggestedTemplates) {
    const corrections = generateCorrections(validation, { placeholders: test.placeholders });
    actual.suggestedTemplates = corrections.map(c => c.suggestedTemplate);
  }

  // Check if actual matches expected
  let passed = true;

  if (test.expected.pass !== undefined && actual.pass !== test.expected.pass) {
    passed = false;
  }

  if (test.expected.errors !== undefined && actual.errors !== test.expected.errors) {
    passed = false;
  }

  if (test.expected.warnings !== undefined && actual.warnings !== test.expected.warnings) {
    passed = false;
  }

  if (test.expected.suggestedTemplates) {
    const suggestedMatch = test.expected.suggestedTemplates.some(expected =>
      actual.suggestedTemplates?.includes(expected)
    );
    if (!suggestedMatch) {
      passed = false;
    }
  }

  return { passed, actual };
}

/**
 * Run tests
 */
if (import.meta.url === `file://${process.argv[1]}`) {
  const allPassed = runTests();
  process.exit(allPassed ? 0 : 1);
}

export { runTests };

#!/usr/bin/env node
/**
 * Semantic Validation Framework
 * 
 * Validates logical consistency between template choice and content structure.
 */

/**
 * Semantic validation rules
 */
const VALIDATION_RULES = {
  flowchart_requires_decisions: {
    template: 'flowchart',
    check: (placeholders) => {
      const hasDecisions = Object.keys(placeholders).some(k => 
        k.includes('DECISION') || k.includes('CHOICE')
      );
      return {
        pass: hasDecisions,
        level: 'WARNING',
        message: hasDecisions ? null : 'Flowchart without DECISION placeholders suggests sequential flow. Consider state-diagram or timeline.',
        suggestion: hasDecisions ? null : {
          templates: ['state-diagram', 'timeline'],
          reason: 'Sequential progression without branching logic'
        }
      };
    }
  },

  timeline_requires_events: {
    template: 'timeline',
    check: (placeholders) => {
      const events = Object.keys(placeholders).filter(k => k.startsWith('EVENT'));
      const dates = Object.keys(placeholders).filter(k => k.startsWith('DATE'));
      const match = events.length === dates.length && events.length > 0;
      return {
        pass: match,
        level: 'ERROR',
        message: match ? null : `Timeline has ${events.length} events but ${dates.length} dates.`,
        suggestion: null
      };
    }
  },

  architecture_requires_components: {
    template: 'architecture',
    check: (placeholders) => {
      const hasComponents = Object.keys(placeholders).some(k =>
        k.includes('COMPONENT') || k.includes('SYSTEM') || k.includes('EXTERNAL')
      );
      return {
        pass: hasComponents,
        level: 'WARNING',
        message: hasComponents ? null : 'Architecture without COMPONENT/SYSTEM placeholders.',
        suggestion: hasComponents ? null : {
          templates: ['flowchart', 'sequence'],
          reason: 'Process flow, not component structure'
        }
      };
    }
  },

  sequence_requires_actors: {
    template: 'sequence',
    check: (placeholders) => {
      const actors = Object.keys(placeholders).filter(k => k.startsWith('ACTOR'));
      const messages = Object.keys(placeholders).filter(k => k.startsWith('MESSAGE'));
      const hasInteractions = actors.length >= 2 && messages.length > 0;
      return {
        pass: hasInteractions,
        level: 'WARNING',
        message: hasInteractions ? null : `Sequence needs multiple actors and messages.`,
        suggestion: hasInteractions ? null : {
          templates: ['flowchart', 'state-diagram'],
          reason: 'Single-actor process flow'
        }
      };
    }
  },

  state_diagram_requires_states: {
    template: 'state-diagram',
    check: (placeholders) => {
      const states = Object.keys(placeholders).filter(k => k.startsWith('STATE'));
      const transitions = Object.keys(placeholders).filter(k => k.includes('TRANSITION'));
      const hasProgression = states.length >= 3 && transitions.length >= 2;
      return {
        pass: hasProgression,
        level: 'WARNING',
        message: hasProgression ? null : `State diagram needs multiple states and transitions.`,
        suggestion: hasProgression ? null : {
          templates: ['flowchart'],
          reason: 'Simple decision flow'
        }
      };
    }
  },

  comparison_table_vs_quadrant: {
    template: 'comparison',
    check: (placeholders) => {
      const hasCoordinates = Object.keys(placeholders).some(k => k.includes('X_') || k.includes('Y_'));
      return {
        pass: hasCoordinates,
        level: 'ERROR',
        message: hasCoordinates ? null : 'Comparison (quadrant) requires X/Y coordinates. Use comparison-table for side-by-side.',
        suggestion: hasCoordinates ? null : {
          templates: ['comparison-table'],
          reason: 'Feature comparison without 2D positioning'
        }
      };
    }
  },

  gantt_requires_temporal: {
    template: 'gantt',
    check: (placeholders) => {
      const tasks = Object.keys(placeholders).filter(k => k.includes('TASK'));
      const starts = Object.keys(placeholders).filter(k => k.includes('START'));
      const durations = Object.keys(placeholders).filter(k => k.includes('DURATION'));
      const hasTemporal = tasks.length > 0 && starts.length > 0 && durations.length > 0;
      return {
        pass: hasTemporal,
        level: 'ERROR',
        message: hasTemporal ? null : 'Gantt requires tasks with start dates and durations.',
        suggestion: hasTemporal ? null : {
          templates: ['timeline', 'state-diagram'],
          reason: 'Sequential progression without time constraints'
        }
      };
    }
  },

  class_diagram_requires_oop: {
    template: 'class-diagram',
    check: (placeholders) => {
      const classes = Object.keys(placeholders).filter(k => k.includes('CLASS'));
      const attrs = Object.keys(placeholders).filter(k => k.includes('ATTR'));
      const methods = Object.keys(placeholders).filter(k => k.includes('METHOD'));
      const hasOOP = classes.length >= 2 && (attrs.length > 0 || methods.length > 0);
      return {
        pass: hasOOP,
        level: 'WARNING',
        message: hasOOP ? null : 'Class diagram needs multiple classes with attributes/methods.',
        suggestion: hasOOP ? null : {
          templates: ['architecture', 'flowchart'],
          reason: 'Component structure or process flow, not object model'
        }
      };
    }
  }
};

export function validateSemantics(template, placeholders) {
  const results = {
    template,
    passed: true,
    errors: [],
    warnings: [],
    suggestions: []
  };

  const rules = Object.entries(VALIDATION_RULES).filter(([_, rule]) => rule.template === template);

  for (const [ruleName, rule] of rules) {
    const result = rule.check(placeholders);

    if (!result.pass) {
      if (result.level === 'ERROR') {
        results.errors.push({ rule: ruleName, message: result.message, suggestion: result.suggestion });
        results.passed = false;
      } else if (result.level === 'WARNING') {
        results.warnings.push({ rule: ruleName, message: result.message, suggestion: result.suggestion });
      }
    }

    if (result.suggestion) {
      results.suggestions.push({ rule: ruleName, ...result.suggestion });
    }
  }

  return results;
}

export function generateCorrections(validationResults, originalContent) {
  const corrections = [];

  for (const suggestion of validationResults.suggestions) {
    for (const suggestedTemplate of suggestion.templates) {
      corrections.push({
        suggestedTemplate,
        reason: suggestion.reason,
        confidence: 0.8,
        originalTemplate: validationResults.template
      });
    }
  }

  return corrections.sort((a, b) => b.confidence - a.confidence);
}

